final class RegistrationOperationsExperience
{
    private const ROUTES=['/admin/registrations','/admin/registrations/edit','/admin/registrations/view','/admin/registrations/intake'];
    private static function registrationNav(string $selected):array
    {
        return [
            ['label'=>'Opportunities','href'=>'/admin/registrations','active'=>$selected==='opportunities'],
            ['label'=>'Submissions','href'=>'/admin/registrations?view=submissions','active'=>$selected==='submissions'],
            ['label'=>'Intake','href'=>'/admin/registrations?view=intake','active'=>$selected==='intake'],
        ];
    }

    public static function handles(string $route):bool{return in_array($route,self::ROUTES,true);}

    public static function render(string $route,string $basePath):never
    {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$user=Auth::currentUser($db);if(!$user||!AccessPolicy::canManageForms($user))self::forbidden();$_SESSION['registration_ops_csrf']??=bin2hex(random_bytes(24));
        if($_SERVER['REQUEST_METHOD']==='POST')self::handlePost($db,$user,$basePath,$route);
        if($route==='/admin/registrations/intake'){header('Cache-Control: private, no-store, max-age=0');header('Pragma: no-cache');header('X-Robots-Tag: noindex, nofollow');header('Referrer-Policy: no-referrer');$submissionId=filter_input(INPUT_GET,'submission',FILTER_VALIDATE_INT)?:0;$intake=RegistrationIntakeService::review($db,(int)$submissionId);self::intakePage($user,$basePath,$intake);}
        $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$opportunity=$id?self::opportunity($db,(int)$id):null;
        if($route==='/admin/registrations/edit'&&!$id&&isset($_GET['production_id'])){
            $requestedId=filter_input(INPUT_GET,'production_id',FILTER_VALIDATE_INT)?:0;
            if(!$requestedId||!self::productionAuditionDefaults($db,(int)$requestedId)){
                http_response_code(404);
                header('Content-Type: text/plain; charset=utf-8');
                exit('This production is unavailable for audition setup. Return to Productions and select a current or upcoming show.');
            }
        }
        $submissions=$opportunity?RegistrationService::submissions($db,(int)$opportunity['id']):[];self::page($db,$user,$basePath,$route,$opportunity,$submissions);
    }

    private static function handlePost(PDO $db,array $user,string $basePath,string $route):never
    {
        if(!hash_equals((string)($_SESSION['registration_ops_csrf']??''),(string)($_POST['csrf_token']??''))){self::flash('error','Your session expired.');self::redirect($basePath.'/admin/registrations');}
        try{
            $action=(string)($_POST['action']??'');
            if($action==='save_opportunity'){$id=self::saveOpportunity($db,$user,$_POST);$saved=self::opportunity($db,$id);$audition=$saved&&$saved['opportunity_type']==='audition';self::flash('success',$audition?'Audition saved.':'Signup saved.');self::redirect($basePath.'/admin/registrations/edit?id='.$id);}
            if($action==='submission_status'){$opportunityId=(int)($_POST['opportunity_id']??0);self::updateSubmission($db,$user,$_POST);self::flash('success','Registration status updated and the family notification was queued when the status changed.');self::redirect($basePath.'/admin/registrations/view?id='.$opportunityId);}
            if($action==='link_existing'){$submissionId=(int)($_POST['submission_id']??0);$participantId=(int)($_POST['participant_user_id']??0);$guardianId=(int)($_POST['guardian_user_id']??0);RegistrationIntakeService::linkExisting($db,$user,$submissionId,$participantId,$guardianId?:null);AuditionIntakeBridge::syncAccepted($db,$submissionId,(int)$user['id']);self::flash('success','Registration linked to existing CTSMD records.');self::redirect($basePath.'/admin/registrations/intake?submission='.$submissionId);}
            if($action==='create_records'){$submissionId=(int)($_POST['submission_id']??0);RegistrationIntakeService::createFromRegistration($db,$user,$submissionId);AuditionIntakeBridge::syncAccepted($db,$submissionId,(int)$user['id']);self::flash('success','CTSMD person/household records linked. Accepted student auditions enter the casting board as Under Review; production roster access remains separate.');self::redirect($basePath.'/admin/registrations/intake?submission='.$submissionId);}
            throw new RuntimeException('Choose a valid registration action.');
        }catch(RuntimeException $e){self::flash('error',$e->getMessage());$submissionId=(int)($_POST['submission_id']??0);if($submissionId)self::redirect($basePath.'/admin/registrations/intake?submission='.$submissionId);$id=(int)($_POST['opportunity_id']??$_POST['id']??0);self::redirect($basePath.($id?'/admin/registrations/edit?id='.$id:'/admin/registrations'));}
    }

    private static function saveOpportunity(PDO $db,array $user,array $input):int
    {
        $id=(int)($input['id']??0);
        $existing=$id?self::opportunity($db,$id):null;
        if($id&&!$existing)throw new RuntimeException('This signup no longer exists.');
        $title=trim((string)($input['title']??''));$slug=strtolower(trim((string)($input['slug']??'')));$slug=preg_replace('/[^a-z0-9-]+/','-',$slug)?:'';$slug=trim($slug,'-');$type=(string)($input['opportunity_type']??'event');$summary=trim((string)($input['summary']??''));$details=trim((string)($input['details']??''));$location=trim((string)($input['location']??''));$status=(string)($input['status']??'draft');$productionId=filter_var($input['production_id']??null,FILTER_VALIDATE_INT)?:null;// Preserve the workflow on edits. Production auditions cannot be converted to general signups.
        if($existing){
            $type=(string)$existing['opportunity_type'];
            if($type==='audition')$productionId=(int)$existing['production_id'];
        }elseif($type==='audition'&&!$productionId){
            throw new RuntimeException('Auditions must be created from a production workspace.');
        }elseif(!in_array($type,['event','interest','audition'],true)){
            throw new RuntimeException('Choose an event signup or interest form.');
        }
        if($type==='audition'&&!$productionId)throw new RuntimeException('Choose a production for auditions.');
        $capacity=filter_var($input['capacity']??null,FILTER_VALIDATE_INT);$capacity=$capacity!==false&&$capacity!==null&&$capacity>0?(int)$capacity:null;$starts=self::dt((string)($input['starts_at']??''));$ends=self::dt((string)($input['ends_at']??''));
        // Linked production auditions always use the production's own audition dates.
        // Staff cannot accidentally create a conflicting second calendar here.
        if($type==='audition'&&$productionId){
            $dates=$db->prepare('SELECT audition_starts_at,audition_ends_at FROM productions WHERE id=:id');
            $dates->execute(['id'=>$productionId]);$source=$dates->fetch();
            if(!$source)throw new RuntimeException('Select an existing production for this audition.');
            $starts=$source['audition_starts_at']?:null;$ends=$source['audition_ends_at']?:null;
        }
        $opens=self::dt((string)($input['registration_opens_at']??''));$closes=self::dt((string)($input['registration_closes_at']??''));$confirmation=trim((string)($input['confirmation_message']??''));$allowVideo=$type==='audition'&&isset($input['allow_audition_video_links'])?1:0;
        if($title===''||mb_strlen($title)>190)throw new RuntimeException('Enter a title no longer than 190 characters.');if($slug===''||mb_strlen($slug)>190)throw new RuntimeException('Enter a public slug.');if(!in_array($type,['audition','event','interest'],true))throw new RuntimeException('CTSMD Connect currently accepts only auditions, selected event signups, and interest/RSVP forms. Classes, camps, and workshops stay in the existing registration system.');if(!in_array($status,['draft','published','closed','archived'],true))throw new RuntimeException('Choose a valid publication status.');if(mb_strlen($summary)>500||mb_strlen($confirmation)>1000)throw new RuntimeException('Summary or confirmation message is too long.');if($ends&&$starts&&$ends<$starts)throw new RuntimeException('End time must be after the start time.');if($closes&&$opens&&$closes<$opens)throw new RuntimeException('Registration close time must be after the open time.');
        $minimumAge=trim((string)($input['minimum_age']??''));$maximumAge=trim((string)($input['maximum_age']??''));
        foreach([$minimumAge,$maximumAge] as $ageValue)if($ageValue!==''&&(!ctype_digit($ageValue)||(int)$ageValue>120))throw new RuntimeException('Age limits must be between 0 and 120.');
        $min=$minimumAge===''?null:(int)$minimumAge;$max=$maximumAge===''?null:(int)$maximumAge;
        if($min!==null&&$max!==null&&$min>$max)throw new RuntimeException('Minimum age cannot exceed maximum age.');
        $cutoff=trim((string)($input['age_eligibility_date']??''));
        if($min===null)throw new RuntimeException('Set a minimum participant age for every audition or signup.');
        if($cutoff===''&&$starts===null)throw new RuntimeException('Set a signup start date or eligibility date to calculate age consistently.');
        if($cutoff!==''&&(!DateTimeImmutable::createFromFormat('!Y-m-d',$cutoff)||DateTimeImmutable::createFromFormat('!Y-m-d',$cutoff)->format('Y-m-d')!==$cutoff))throw new RuntimeException('Enter a valid age eligibility date.');
        try{
            if($id){$stmt=$db->prepare('UPDATE registration_opportunities SET production_id=:production,title=:title,slug=:slug,opportunity_type=:type,summary=:summary,details=:details,location=:location,starts_at=:starts,ends_at=:ends,registration_opens_at=:opens,registration_closes_at=:closes,capacity=:capacity,status=:status,confirmation_message=:confirmation,allow_audition_video_links=:allow_video,minimum_age=:minimum_age,maximum_age=:maximum_age,age_eligibility_date=:cutoff WHERE id=:id');$stmt->execute(['production'=>$productionId,'title'=>$title,'slug'=>$slug,'type'=>$type,'summary'=>$summary?:null,'details'=>$details?:null,'location'=>$location?:null,'starts'=>$starts,'ends'=>$ends,'opens'=>$opens,'closes'=>$closes,'capacity'=>$capacity,'status'=>$status,'confirmation'=>$confirmation?:null,'allow_video'=>$allowVideo,'minimum_age'=>$min,'maximum_age'=>$max,'cutoff'=>$cutoff?:null,'id'=>$id]);$event='registration.opportunity_updated';}
            else{$stmt=$db->prepare('INSERT INTO registration_opportunities (production_id,title,slug,opportunity_type,summary,details,location,starts_at,ends_at,registration_opens_at,registration_closes_at,capacity,status,confirmation_message,allow_audition_video_links,created_by_user_id,minimum_age,maximum_age,age_eligibility_date) VALUES (:production,:title,:slug,:type,:summary,:details,:location,:starts,:ends,:opens,:closes,:capacity, :status,:confirmation,:allow_video,:creator,:minimum_age,:maximum_age,:cutoff)');$stmt->execute(['production'=>$productionId,'title'=>$title,'slug'=>$slug,'type'=>$type,'summary'=>$summary?:null,'details'=>$details?:null,'location'=>$location?:null,'starts'=>$starts,'ends'=>$ends,'opens'=>$opens,'closes'=>$closes,'capacity'=>$capacity,'status'=>$status,'confirmation'=>$confirmation?:null,'allow_video'=>$allowVideo,'minimum_age'=>$min,'maximum_age'=>$max,'cutoff'=>$cutoff?:null,'creator'=>(int)$user['id']]);$id=(int)$db->lastInsertId();$event='registration.opportunity_created';}
        }catch(PDOException $e){if((string)$e->getCode()==='23000')throw new RuntimeException('That public slug is already in use.');throw new RuntimeException('The registration signup could not be saved.');}
        self::audit($db,(int)$user['id'],$event,'registration_opportunity',$id,'Saved public registration signup.',['status'=>$status,'production_id'=>$productionId]);return $id;
    }

    private static function updateSubmission(PDO $db,array $user,array $input):void
    {
        $submissionId=(int)($input['submission_id']??0);$opportunityId=(int)($input['opportunity_id']??0);$status=(string)($input['status']??'');if($submissionId<1||$opportunityId<1||!in_array($status,['submitted','waitlisted','accepted','declined','cancelled'],true))throw new RuntimeException('Choose a valid registration status.');
        $beforeStmt=$db->prepare('SELECT status FROM registration_submissions WHERE id=:id AND opportunity_id=:opportunity LIMIT 1');$beforeStmt->execute(['id'=>$submissionId,'opportunity'=>$opportunityId]);$before=$beforeStmt->fetchColumn();if($before===false)throw new RuntimeException('That registration could not be found.');if((string)$before===$status){if($status==='accepted')AuditionIntakeBridge::syncAccepted($db,$submissionId,(int)$user['id']);elseif(in_array($status,['declined','cancelled'],true))AuditionIntakeBridge::withdrawPending($db,$submissionId,(int)$user['id']);return;}
        $stmt=$db->prepare('UPDATE registration_submissions SET status=:status,reviewed_by_user_id=:reviewer,reviewed_at=CURRENT_TIMESTAMP WHERE id=:id AND opportunity_id=:opportunity');$stmt->execute(['status'=>$status,'reviewer'=>(int)$user['id'],'id'=>$submissionId,'opportunity'=>$opportunityId]);if(!$stmt->rowCount())throw new RuntimeException('That registration could not be updated.');self::audit($db,(int)$user['id'],'registration.status_updated','registration_submission',$submissionId,'Updated registration review status.',['before'=>$before,'status'=>$status,'opportunity_id'=>$opportunityId]);RegistrationStatusNotificationService::queue($db,$submissionId,(string)$before);if($status==='accepted')AuditionIntakeBridge::syncAccepted($db,$submissionId,(int)$user['id']);
    }

    private static function opportunity(PDO $db,int $id):?array{$s=$db->prepare('SELECT ro.*,p.title production_title FROM registration_opportunities ro LEFT JOIN productions p ON p.id=ro.production_id WHERE ro.id=:id LIMIT 1');$s->execute(['id'=>$id]);return $s->fetch()?:null;}
    private static function productions(PDO $db):array{return $db->query("SELECT id,title,season,is_active,lifecycle_stage,audition_starts_at,performance_starts_at FROM productions ORDER BY CASE WHEN lifecycle_stage IN ('completed','archived') THEN 1 ELSE 0 END ASC, CASE WHEN lifecycle_stage IN ('completed','archived') THEN COALESCE(performance_starts_at,audition_starts_at) END DESC, CASE WHEN lifecycle_stage NOT IN ('completed','archived') THEN COALESCE(audition_starts_at,performance_starts_at) END ASC, title ASC")->fetchAll();}

    /** Prefill a new audition using authoritative production dates and age rules.
     *  Never overwrite an existing opportunity; staff explicitly reviews/publishes. */
    private static function productionAuditionDefaults(PDO $db,int $productionId):?array
    {
        if($productionId<1)return null;
        $stmt=$db->prepare("SELECT id,title,season,is_active,lifecycle_stage,participant_category,student_minimum_age,student_maximum_age,participant_eligibility_date,audition_starts_at,audition_ends_at FROM productions WHERE id=:id LIMIT 1");
        $stmt->execute(['id'=>$productionId]);$p=$stmt->fetch();
        if(!$p||in_array((string)$p['lifecycle_stage'],['completed','archived'],true))return null; // Planning/upcoming productions can have auditions before activation.
        $title=trim((string)$p['title']).' Auditions';
        $slug=trim(preg_replace('/[^a-z0-9]+/','-',strtolower((string)$p['title']))??'','-').'-auditions-'.$productionId;
        $starts=$p['audition_starts_at']?:null;$ends=$p['audition_ends_at']?:null;
        $cutoff=$p['participant_eligibility_date']?:($starts?substr((string)$starts,0,10):null);
        return [
            'id'=>0,'production_id'=>$productionId,'title'=>$title,'slug'=>$slug,
            'opportunity_type'=>'audition','summary'=>'Audition registration for '.trim((string)$p['title']).'.',
            'details'=>'','location'=>'','starts_at'=>$starts,'ends_at'=>$ends,
            'registration_opens_at'=>null,'registration_closes_at'=>$ends?substr((string)$ends,0,10).' 23:59:00':null,
            'capacity'=>null,'status'=>'draft','confirmation_message'=>'','allow_audition_video_links'=>0,
            'minimum_age'=>$p['student_minimum_age']??null,'maximum_age'=>$p['student_maximum_age']??null,
            'age_eligibility_date'=>$cutoff,'production_prefilled'=>true,
        ];
    }
    private static function dt(string $value):?string{$value=trim($value);if($value==='')return null;$ts=strtotime($value);if($ts===false)throw new RuntimeException('One of the dates or times is invalid.');return date('Y-m-d H:i:s',$ts);}

    private static function intakePage(array $user,string $basePath,?array $intake):never
    {
        $e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$u=static fn(string $p):string=>($basePath?:'').$p;$flash=$_SESSION['registration_ops_flash']??null;unset($_SESSION['registration_ops_flash']);header('Content-Type:text/html; charset=utf-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Intake Review · CTSMD Connect</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/registration-ops.css')?>"><?php WorkspaceUI::operationsStyles($basePath); ?></head><body class="app-body ux-operations ux-workspace"><div class="unified-shell"><?php AppNavigation::renderSidebar('/admin/registrations/intake',$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Operations','Registration Intake',$basePath,self::registrationNav('intake'));?><div class="regops-page ops-page"><?php if($flash):?><div class="regops-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?><?php if(!$intake):?><section class="regops-empty"><b>Registration not found.</b><p>This intake record may no longer exist.</p><a href="<?=$u('/admin/registrations')?>">Back to Registration Operations</a></section><?php else:?><section class="regops-head ops-heading"><div><small>REVIEWED INTAKE</small><h2><?=$e($intake['participant_first_name'].' '.$intake['participant_last_name'])?></h2><p><?=$e($intake['opportunity_title'])?><?=$intake['production_title']?' · '.$e($intake['production_title']):''?></p></div><a href="<?=$u('/admin/registrations/view?id='.(int)$intake['opportunity_id'])?>">← Registrants</a></section>
        <?php if(($intake['audition_link_status']??'')==='awaiting_identity'):?><section class="regops-intake-card ops-panel"><b>Audition identity pending</b><p>Link the registered child to an active CTSMD Student and an authorized guardian. The parent must not become the casting participant.</p></section><?php endif;?><div class="regops-intake-grid"><section class="regops-intake-card ops-panel"><small>SUBMITTED INFORMATION</small><dl><div><dt>Status</dt><dd><?=ucfirst($e((string)$intake['status']))?></dd></div><div><dt>Age</dt><dd><?=$intake['participant_declared_age']!==null?(int)$intake['participant_declared_age']:$e(str_replace('_','–',(string)$intake['participant_age_group']))?></dd></div><div><dt>Age evidence</dt><dd><?=$e(match((string)$intake['age_evidence']){'account_dob'=>'Account date of birth','guest_declared'=>'Guest age · self-reported',default=>'Historical age group · review needed'})?></dd></div><div><dt>Contact</dt><dd><?=$e((string)$intake['registrant_email'])?></dd></div><?php if($intake['guardian_name']):?><div><dt>Guardian</dt><dd><?=$e((string)$intake['guardian_name'])?> · <?=$e((string)$intake['guardian_email'])?></dd></div><?php endif;?></dl><?php if($intake['notes']):?><p><?=$e((string)$intake['notes'])?></p><?php endif;?><?php if(($intake['opportunity_type']??'')==='audition'&&!empty($intake['audition_video_url'])):?><div class="regops-support-detail"><b>Submitted audition video</b><p><a href="<?=$e((string)$intake['audition_video_url'])?>" target="_blank" rel="noopener noreferrer">Open submitted video link ↗</a></p><small>External link supplied by the participant. Check the destination before opening.</small></div><?php endif;?><?php if(trim((string)($intake['allergy_information']??''))!==''):?><div class="regops-support-detail"><b>Allergies / sensitivities</b><p><?=nl2br($e((string)$intake['allergy_information']))?></p></div><?php endif;?><?php if(trim((string)($intake['accommodation_information']??''))!==''):?><div class="regops-support-detail"><b>Accommodations / accessibility</b><p><?=nl2br($e((string)$intake['accommodation_information']))?></p></div><?php endif;?></section>
        <?php if($intake['participant_user_id']):?><section class="regops-intake-card ops-panel linked"><small>CTSMD RECORDS LINKED</small><h3><?=$e((string)$intake['linked_participant_name'])?></h3><p>Participant record #<?=(int)$intake['participant_user_id']?> · <?=ucfirst($e((string)$intake['link_method']))?> linking</p><?php if(isset($intake['audition_link_status'])):?><p><b>Audition status:</b> <?=$e(match($intake['audition_link_status']){'in_casting'=>'In casting · '.ucwords(str_replace('_',' ',(string)$intake['linked_casting_status'])),'awaiting_guardian_verification'=>'Awaiting guardian verification','awaiting_casting_sync'=>'Approved · needs casting intake sync','linked_awaiting_approval'=>'Linked · awaiting registration approval',default=>'Awaiting student identity'})?></p><?php endif;?><?php if($intake['linked_guardian_name']):?><p>Guardian: <b><?=$e((string)$intake['linked_guardian_name'])?></b></p><?php endif;?><nav><a href="<?=$u('/people/view?id='.(int)$intake['participant_user_id'])?>">Open participant</a><?php if($intake['guardian_user_id']):?><a href="<?=$u('/people/view?id='.(int)$intake['guardian_user_id'])?>">Open guardian</a><?php endif;?></nav><div class="regops-boundary"><b>Audition casting</b><span>Accepted auditions linked to a Student in this production enter Casting as Under Review. The child is not added to the production roster until casting is confirmed.</span></div></section>
        <?php else:?><section class="regops-intake-card ops-panel"><small>LIKELY MATCHES</small><h3>Link existing CTSMD records</h3><p>Review the matches before linking. Email is the strongest adult match; student matching uses the submitted name and guardian relationship.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['registration_ops_csrf'])?>"><input type="hidden" name="action" value="link_existing"><input type="hidden" name="submission_id" value="<?=(int)$intake['id']?>"><label>Participant<select name="participant_user_id" required><option value="">Choose an existing person…</option><?php foreach($intake['participant_candidates'] as $candidate):?><option value="<?=(int)$candidate['id']?>"><?=$e($candidate['name'])?> · <?=$e((string)($candidate['email']?:$candidate['display_role']))?><?php if(!empty($candidate['guardian_email'])):?> · guardian <?=$e((string)$candidate['guardian_email'])?><?php endif;?></option><?php endforeach;?></select></label><?php if($intake['participant_age_group']!=='adult'):?><label>Guardian<select name="guardian_user_id" required><option value="">Choose guardian…</option><?php foreach($intake['guardian_candidates'] as $candidate):?><option value="<?=(int)$candidate['id']?>"><?=$e($candidate['name'])?> · <?=$e((string)$candidate['email'])?></option><?php endforeach;?></select></label><?php endif;?><button type="submit"<?=$intake['participant_candidates']&&($intake['participant_age_group']==='adult'||$intake['guardian_candidates'])?'':' disabled'?>>Link selected records</button></form></section><section class="regops-intake-card ops-panel create"><small>NO SAFE MATCH?</small><h3>Create reviewed CTSMD records</h3><p><?=$intake['participant_age_group']==='adult'?'Creates or reuses an adult person record using the submitted email. It does not automatically approve membership or send an invitation.':'Creates or reuses the guardian by email, creates/reuses a managed Student, and establishes the guardian relationship in one transaction.'?></p><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['registration_ops_csrf'])?>"><input type="hidden" name="action" value="create_records"><input type="hidden" name="submission_id" value="<?=(int)$intake['id']?>"><button type="submit">Create / reuse CTSMD records</button></form><div class="regops-boundary"><b>Still separate from production access</b><span>This does not add the participant to <?=$e((string)($intake['production_title']?:'a production'))?> or unlock production channels.</span></div></section><?php endif;?></div><?php endif;?></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }

    private static function page(PDO $db,array $user,string $basePath,string $route,?array $opportunity,array $submissions):never
    {
        $e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$u=static fn(string $p):string=>($basePath?:'').$p;$flash=$_SESSION['registration_ops_flash']??null;unset($_SESSION['registration_ops_flash']);$allSignups=array_values(array_filter(RegistrationService::allOpportunities($db),static fn(array $o):bool=>$o['opportunity_type']!=='audition' && ($o['production_id']===null||($o['production_lifecycle_stage']??'')!=='archived')));
        $opportunities=array_values(array_filter($allSignups,static fn(array $o):bool=>$o['status']!=='archived'));
        $archivedSignups=array_values(array_filter($allSignups,static fn(array $o):bool=>$o['status']==='archived'));
        $productions=self::productions($db);$isAuditionEditor=$route==='/admin/registrations/edit'&&(($opportunity&&$opportunity['opportunity_type']==='audition')||(!empty($_GET['production_id'])&&ctype_digit((string)$_GET['production_id'])));$title=$route==='/admin/registrations'?'Signups & Registration':($route==='/admin/registrations/view'?'Registrants':($isAuditionEditor?'Manage Auditions':'Manage Signup'));header('Content-Type:text/html; charset=utf-8');?>
        <!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$e($title)?> · CTSMD Connect</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/registration-ops.css')?>"><?php WorkspaceUI::operationsStyles($basePath); ?></head><body class="app-body ux-operations ux-workspace"><div class="unified-shell"><?php AppNavigation::renderSidebar($route,$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Operations',$title,$basePath,self::registrationNav($route==='/admin/registrations'?(string)($_GET['view']??'opportunities'):($route==='/admin/registrations/view'?'submissions':'opportunities')));?><div class="regops-page ops-page"><?php if($flash):?><div class="regops-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?>
        <?php if($route==='/admin/registrations'):$listingView=in_array((string)($_GET['view']??''),['submissions','intake'],true)?(string)$_GET['view']:'opportunities';?><section class="regops-hero ops-heading"><div><small>PUBLIC SIGNUPS</small><h2><?=$listingView==='submissions'?'Registration submissions':($listingView==='intake'?'Participant intake':'Signups &amp; Registration')?></h2><p><?=$listingView==='submissions'?'Choose an opportunity to review its registered participants and submission statuses.':($listingView==='intake'?'Choose an opportunity with registrations, then open a participant’s CTSMD person / household review.':'Create event signups and interest forms. Production auditions are created and managed within each production.')?></p></div><a href="<?=$u('/admin/registrations/edit')?>">+ New signup</a></section><div class="regops-list"><?php if(!$opportunities):?><div class="regops-empty">No current signups to show.</div><?php endif;?><?php foreach($opportunities as $o):if($listingView!=='opportunities'&&(int)$o['active_registrations']<1&&(int)$o['waitlisted_registrations']<1)continue;?><article><div><small><?=$e(strtoupper($o['status'].' · '.$o['opportunity_type']))?></small><h3><?=$e($o['title'])?></h3><p><?=$e((string)($o['production_title']?:'Organization-wide'))?> · <?=$o['starts_at']?$e(date('m/d/Y · g:i A',strtotime($o['starts_at']))):'Date not scheduled'?></p></div><div class="regops-count"><b><?=(int)$o['active_registrations']?></b><span>active</span><?php if((int)$o['waitlisted_registrations']>0):?><em><?=(int)$o['waitlisted_registrations']?> waitlisted</em><?php endif;?></div><nav><a href="<?=$u('/admin/registrations/view?id='.(int)$o['id'])?>"><?=$listingView==='intake'?'Review participants':($listingView==='submissions'?'View submissions':'Registrants')?></a><a href="<?=$u('/admin/registrations/edit?id='.(int)$o['id'])?>">Edit</a><?php if($o['status']==='published'&&in_array($o['opportunity_type'],['event','interest'],true)):?><a target="_blank" rel="noopener" href="<?=$u('/register?slug='.rawurlencode($o['slug']))?>">Public ↗</a><?php endif;?></nav></article><?php endforeach;?></div>
        <?php if($archivedSignups):?><details class="regops-archive" style="margin-top:18px;border:1px solid #e4dcd5;border-radius:10px;background:#fff;padding:12px 16px"><summary style="cursor:pointer;font-weight:700;min-height:32px">Archived signups (<?=count($archivedSignups)?>)</summary><div class="regops-list" style="margin-top:12px"><?php foreach($archivedSignups as $o):?><article><div><small><?=$e(strtoupper('ARCHIVED · '.$o['opportunity_type']))?></small><h3><?=$e($o['title'])?></h3><p><?=$e((string)($o['production_title']?:'Organization-wide'))?> · <?=$o['starts_at']?$e(date('m/d/Y',strtotime($o['starts_at']))):'No date'?></p></div><div class="regops-count"><b><?=(int)$o['active_registrations']?></b><span>registered</span></div><nav><a href="<?=$u('/admin/registrations/view?id='.(int)$o['id'])?>">View registrants</a><a href="<?=$u('/admin/registrations/edit?id='.(int)$o['id'])?>">View / edit</a></nav></article><?php endforeach;?></div></details><?php endif;?>
        <?php elseif($route==='/admin/registrations/edit'):$prefill=(!$opportunity&&isset($_GET['production_id'])&&ctype_digit((string)$_GET['production_id']))?self::productionAuditionDefaults($db,(int)$_GET['production_id']):null;$o=$opportunity?:($prefill?:['id'=>0,'production_id'=>null,'title'=>'','slug'=>'','opportunity_type'=>'event','summary'=>'','details'=>'','location'=>'','starts_at'=>null,'ends_at'=>null,'registration_opens_at'=>null,'registration_closes_at'=>null,'capacity'=>null,'status'=>'draft','confirmation_message'=>'','allow_audition_video_links'=>0,'allow_audition_video_links'=>0,'minimum_age'=>null,'maximum_age'=>null ,'age_eligibility_date'=>null]);if($o['id']&&$o['opportunity_type']==='audition'&&$o['production_id']){
        $linkedDates=$db->prepare('SELECT audition_starts_at,audition_ends_at FROM productions WHERE id=:id');
        $linkedDates->execute(['id'=>(int)$o['production_id']]);$linked=$linkedDates->fetch();
        if($linked){$o['starts_at']=$linked['audition_starts_at'];$o['ends_at']=$linked['audition_ends_at'];}
    }?><section class="regops-head ops-heading"><div><small><?=$o['opportunity_type']==='audition'?'PRODUCTION AUDITION':($o['id']?'EDIT SIGNUP':'NEW SIGNUP')?></small><h2><?=$o['id']?$e($o['title']):(!empty($o['production_prefilled'])?'Create auditions':'Create signup')?></h2><?php if(!empty($o['production_prefilled'])):?><p>Production title, age eligibility and audition dates are prefilled. Review the details, registration window, and publication status before saving. Audition dates always follow the production timeline. Registration opening and closing dates can be set separately.</p><?php endif;?></div><a href="<?=$u($o['opportunity_type']==='audition'&&!empty($o['production_id'])?'/admin/productions/view?id='.(int)$o['production_id'].'#production-auditions':'/admin/registrations')?>">← <?=$o['opportunity_type']==='audition'?'Production auditions':'Signups & registration'?></a></section><form class="regops-form ops-form" method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['registration_ops_csrf'])?>"><input type="hidden" name="id" value="<?=(int)$o['id']?>"><input type="hidden" name="action" value="save_opportunity"><div class="pair"><label>Title<input name="title" maxlength="190" value="<?=$e((string)$o['title'])?>" required></label><label>Public slug<input name="slug" maxlength="190" value="<?=$e((string)$o['slug'])?>" placeholder="frozen-auditions" required></label></div><div class="pair"><?php if($o['opportunity_type']==='audition'):?><input type="hidden" name="opportunity_type" value="audition"><div class="regops-hint"><strong>Production audition.</strong> This form is dedicated to auditions for the selected show. Other signups are managed in Operations.</div><?php else:?><label>Signup type<select name="opportunity_type"><?php $types=['event'=>'Special event / signup','interest'=>'Interest / RSVP'];if(!isset($types[$o['opportunity_type']])):?><option value="<?=$e((string)$o['opportunity_type'])?>" selected><?=ucfirst($e((string)$o['opportunity_type']))?> · legacy/external type</option><?php endif;?><?php foreach($types as $value=>$label):?><option value="<?=$value?>"<?=$o['opportunity_type']===$value?' selected':''?>><?=$e($label)?></option><?php endforeach;?></select><small>Classes, camps and workshops stay in the existing registration system.</small></label><?php endif;?><label>Status<select name="status"><?php foreach(['draft','published','closed','archived'] as $status):?><option value="<?=$status?>"<?=$o['status']===$status?' selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select></label></div><?php if($o['opportunity_type']==='audition'):?><input type="hidden" name="production_id" value="<?=(int)$o['production_id']?>"><div class="regops-hint"><strong>Production:</strong> <?php foreach($productions as $p){if((int)$p['id']===(int)$o['production_id']){echo $e((string)$p['title']);break;}} ?> · <a href="<?=$u('/admin/productions/view?id='.(int)$o['production_id'])?>">Manage production</a></div><?php else:?><label>Related production <span>optional</span><select name="production_id"><option value="">Organization-wide / not tied to a show</option><?php foreach($productions as $p):?><option value="<?=(int)$p['id']?>"<?=(int)$o['production_id']===(int)$p['id']?' selected':''?>><?=$e($p['title'])?><?=$p['season']?' · '.$e($p['season']):''?><?=$p['is_active']?'':' · inactive'?></option><?php endforeach;?></select></label><?php endif;?><label>Short public summary<textarea name="summary" maxlength="500" rows="3"><?=$e((string)$o['summary'])?></textarea></label><label>Details<textarea name="details" rows="8"><?=$e((string)$o['details'])?></textarea></label><div class="pair"><label>Location<input name="location" value="<?=$e((string)$o['location'])?>"></label><label>Capacity <span>blank = unlimited</span><input type="number" min="1" name="capacity" value="<?=$o['capacity']!==null?(int)$o['capacity']:''?>"></label></div><?php if($o['opportunity_type']==='audition'&&!empty($o['production_id'])):?><p class="regops-hint">Audition dates are linked to the production timeline. Update them in <a href="<?=$u('/admin/productions/view?id='.(int)$o['production_id'].'#production-lifecycle')?>">Production → Stage &amp; dates</a>. Registration open/close dates below remain independent.</p><?php endif;?><?php if($o['opportunity_type']==='audition'&&!empty($o['production_id'])):?>
<div class="regops-hint"><strong>Audition dates:</strong> <?=!empty($o['starts_at'])?$e(date('m/d/Y',strtotime((string)$o['starts_at']))):'Not scheduled'?> – <?=!empty($o['ends_at'])?$e(date('m/d/Y',strtotime((string)$o['ends_at']))):'Not scheduled'?>. Change these in the production timeline.</div>
<?php else:?><div class="pair"><label>Activity starts<input type="datetime-local" name="starts_at" value="<?=$o['starts_at']?$e(date('Y-m-d\TH:i',strtotime($o['starts_at']))):''?>" <?=($o['opportunity_type']==='audition'&&!empty($o['production_id']))?'readonly title="Managed in production timeline"':''?>></label><label>Activity ends<input type="datetime-local" name="ends_at" value="<?=$o['ends_at']?$e(date('Y-m-d\TH:i',strtotime($o['ends_at']))):''?>" <?=($o['opportunity_type']==='audition'&&!empty($o['production_id']))?'readonly title="Managed in production timeline"':''?>></label></div><?php endif;?><div class="pair"><label>Registration opens<input type="datetime-local" name="registration_opens_at" value="<?=$o['registration_opens_at']?$e(date('Y-m-d\TH:i',strtotime($o['registration_opens_at']))):''?>"></label><label>Registration closes<input type="datetime-local" name="registration_closes_at" value="<?=$o['registration_closes_at']?$e(date('Y-m-d\TH:i',strtotime($o['registration_closes_at']))):''?>"></label></div><fieldset><legend>Participant age eligibility</legend><p>Set the ages allowed for this activity. We check a member's age using their saved birth date. Guests enter their age, which staff may need to verify.</p><div class="pair"><label>Minimum age (required)<input type="number" min="0" max="120" name="minimum_age" required value="<?=$o['minimum_age']!==null?(int)$o['minimum_age']:''?>"></label><label>Maximum age<input type="number" min="0" max="120" name="maximum_age" value="<?=$o['maximum_age']!==null?(int)$o['maximum_age']:''?>"></label></div><label>Age checked on<input type="date" name="age_eligibility_date" value="<?=$e((string)($o['age_eligibility_date']??''))?>"><small><?=!empty($o['age_eligibility_date'])?'Using '.date('m/d/Y',strtotime((string)$o['age_eligibility_date'])).'. ':''?>Age is calculated on this date. If blank, the activity start date is used.</small></label></fieldset><?php if($o['opportunity_type']==='audition'):?><fieldset><legend>Audition video links</legend><label style="display:flex;align-items:center;gap:10px"><input type="checkbox" name="allow_audition_video_links" value="1" <?=!empty($o['allow_audition_video_links'])?'checked':''?> style="width:auto;min-width:18px;height:18px">Allow participants to share an audition video link</label><p>Off by default. When enabled, the public audition form includes an optional HTTPS video URL field. Staff can review the link with the participant’s registration. Video uploads and embedded playback are not enabled.</p></fieldset><?php endif;?><label>Confirmation note <span>optional</span><textarea name="confirmation_message" maxlength="1000" rows="4"><?=$e((string)$o['confirmation_message'])?></textarea></label><button type="submit"><?=$o['opportunity_type']==='audition'?'Save audition':'Save signup'?></button></form>
        <?php else:?><section class="regops-head ops-heading"><div><small>REGISTRANTS</small><h2><?=$opportunity?$e($opportunity['title']):'Opportunity not found'?></h2></div><a href="<?=$u('/admin/registrations')?>">← Registration Operations</a></section><?php if($opportunity):?><div class="regops-review ops-panel"><header><span><?=$e(ucfirst($opportunity['status']))?></span><a href="<?=$u('/admin/registrations/edit?id='.(int)$opportunity['id'])?>">Edit signup</a><?php if($opportunity['status']==='published'&&in_array($opportunity['opportunity_type'],['audition','event','interest'],true)):?><a target="_blank" href="<?=$u('/register?slug='.rawurlencode($opportunity['slug']))?>">Open public page ↗</a><?php endif;?></header><?php if(!$submissions):?><div class="regops-empty">No registrations yet.</div><?php endif;?><?php foreach($submissions as $s):?><article><div class="regops-person"><b><?=$e($s['participant_first_name'].' '.$s['participant_last_name'])?></b><span><?=$s['participant_declared_age']!==null?'Age '.(int)$s['participant_declared_age']:$e(str_replace('_','–',$s['participant_age_group']))?> · <?=$e($s['registrant_email'])?> · <?=$e($s['age_evidence']==='guest_declared'?('Self-reported age'):($s['age_evidence']==='account_dob'?'Account DOB':'Legacy age group'))?></span><?php if($s['guardian_name']):?><small>Guardian: <?=$e($s['guardian_name'])?> · <?=$e((string)$s['guardian_email'])?></small><?php endif;?><?php if($s['notes']):?><p><?=$e($s['notes'])?></p><?php endif;?><?php if($opportunity['opportunity_type']==='audition'&&!empty($s['audition_video_url'])):?><p><a href="<?=$e((string)$s['audition_video_url'])?>" target="_blank" rel="noopener noreferrer">View audition video ↗</a></p><?php endif;?><a class="regops-intake-link" href="<?=$u('/admin/registrations/intake?submission='.(int)$s['id'])?>">Review CTSMD person / household link →</a></div><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['registration_ops_csrf'])?>"><input type="hidden" name="action" value="submission_status"><input type="hidden" name="submission_id" value="<?=(int)$s['id']?>"><input type="hidden" name="opportunity_id" value="<?=(int)$opportunity['id']?>"><select name="status"><?php foreach(['submitted','waitlisted','accepted','declined','cancelled'] as $status):?><option value="<?=$status?>"<?=$s['status']===$status?' selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select><button type="submit">Update</button></form></article><?php endforeach;?></div><?php endif;?><?php endif;?></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }

    private static function audit(PDO $db,int $actor,string $event,string $type,int $id,string $summary,array $meta):void{$s=$db->prepare('INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,:type,:id,:summary,:meta)');$s->execute(['actor'=>$actor,'event'=>$event,'type'=>$type,'id'=>$id,'summary'=>$summary,'meta'=>json_encode($meta,JSON_THROW_ON_ERROR)]);}
    private static function flash(string $type,string $message):void{$_SESSION['registration_ops_flash']=['type'=>$type,'message'=>$message];}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
    private static function forbidden():never{http_response_code(403);exit('Restricted');}
}
